// Medical Assisting Practice Test 1. Original questions written for Valus from the HOSA 2026–27 test
// plan, slightly harder than the sample items: administrative and clinical decisions with their reasons.
import {q, mix} from './q.js';
const BLESI='Blesi, Wise & Kelley-Arney, Medical Assisting: Administrative and Clinical Competencies';
const PRO='Professionalism', COMM='Communication Skills', AP='Anatomy & Physiology and Medical Terminology', LEGAL='Legal and Ethical Issues', OFF='Office Procedures', INS='Health Insurance and Coding', INF='Infection Control', SPEC='Collecting and Processing Specimens', DX='Diagnostic Testing', CLIN='Clinical Procedures and Equipment', EXAM='Physical Examinations';

export default {
 id:'medical-assisting-1',
 event:'Medical Assisting',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Blesi’s Medical Assisting: Administrative and Clinical Competencies',
 plan:[{area:PRO,weight:4},{area:COMM,weight:6},{area:AP,weight:10},{area:LEGAL,weight:10},{area:OFF,weight:10},{area:INS,weight:10},{area:INF,weight:10},{area:SPEC,weight:10},{area:DX,weight:10},{area:CLIN,weight:10},{area:EXAM,weight:10}],
 questions:mix([
  q(PRO,'What is required to sit for the AAMA Certified Medical Assistant (CMA) exam?','Graduating from an accredited program',['Working one year in any medical office','A physician’s recommendation letter','Holding a nursing license'],'B','The CMA (AAMA) exam requires completion of a medical assisting program accredited by CAAHEP or ABHES. Certification must be recertified every 60 months.',BLESI),
  q(PRO,'A patient sends the medical assistant a friend request on social media. What is the professional response?','Decline, to keep professional boundaries',['Accept, to build rapport','Accept, but only discuss health topics','Ask the physician to accept it instead'],'D','Personal social media connections with patients blur professional boundaries and risk privacy breaches. Communication should go through official channels.',BLESI),
  q(COMM,'A patient says, “I’m scared about this biopsy.” The MA replies, “You’re feeling frightened about the test.” Which technique is this?','Reflecting',['Giving advice','False reassurance','Changing the subject'],'A','Reflecting restates the patient’s feelings to show understanding and encourage them to share more. False reassurance (“It’ll be fine”) can shut down conversation.',BLESI),
  q(COMM,'A caller says her husband has crushing chest pain and is sweating. What should the medical assistant do?','Tell her to call 911 now',['Schedule the next available appointment','Take a message for the physician','Advise rest and a call back tomorrow'],'C','Chest pain with sweating may be a heart attack, a life-threatening emergency. Telephone screening sends emergencies directly to 911.',BLESI),
  q(COMM,'During an interview, a patient sits with arms tightly crossed and avoids eye contact. What might this nonverbal behavior suggest?','Defensiveness or discomfort',['Relaxed agreement','Eagerness to talk','Complete understanding'],'B','Crossed arms and avoided eye contact often signal anxiety or defensiveness, though cultural norms vary. The MA can respond by creating privacy and using open-ended questions.',BLESI),
  q(AP,'A patient’s heart rate is 118 beats per minute at rest. Which term describes this?','Tachycardia',['Bradycardia','Arrhythmia','Hypotension'],'D','Tachy- means fast; a resting adult heart rate above 100 is tachycardia. Below 60 is bradycardia.',BLESI),
  q(AP,'In anatomical position, how are the palms facing?','Forward',['Backward','Toward the body','Downward'],'A','Anatomical position is standing upright, facing forward, arms at the sides, palms facing forward. Directional terms are based on this position.',BLESI),
  q(AP,'The spleen, thymus and lymph nodes belong to which body system?','Lymphatic system',['Endocrine system glands','Digestive system','Urinary system'],'C','These organs filter lymph and blood and house immune cells. The thymus is also where T cells mature.',BLESI),
  q(AP,'A patient reports dyspnea. What does this mean?','Difficult breathing',['Painful urination','Difficult swallowing','Abnormal speech'],'B','Dys- means difficult and -pnea means breathing. Dysuria is painful urination, dysphagia is difficulty swallowing, and dysphasia is a speech problem.',BLESI),
  q(AP,'Which phase of the cardiac cycle is the contraction of the ventricles?','Systole',['Diastole','Repolarization','Depolarization'],'D','Systole is ventricular contraction, which produces the top blood pressure number. Diastole is relaxation and filling, the bottom number.',BLESI),
  q(LEGAL,'A patient asks the MA to explain what his abnormal lab result means. What should the MA do?','Refer the question to the physician',['Explain the diagnosis to the patient','Tell the patient the result is probably fine','Look up the result online with the patient'],'A','Interpreting test results and making diagnoses are outside an MA’s scope of practice. The MA should let the provider discuss results.',BLESI),
  q(LEGAL,'Under HIPAA, when must a new patient receive the practice’s Notice of Privacy Practices?','At the first visit',['Only if the patient asks for it','After the patient pays the bill','Once a year at the annual exam'],'C','The Notice of Privacy Practices explains how protected health information is used and the patient’s rights. The office makes a good-faith effort to get written acknowledgment of receipt.',BLESI),
  q(LEGAL,'What role may a medical assistant have in informed consent for a procedure?','Witnessing the patient’s signature',['Explaining the risks and alternatives','Deciding whether the patient understands','Signing for the patient if they agree verbally'],'B','The provider explains the procedure, risks, benefits and alternatives. The MA may witness the signature, confirming who signed, not that the patient understood.',BLESI),
  q(LEGAL,'A former patient’s attorney requests a copy of the medical record. What is required before releasing it?','A signed authorization from the patient',['A phone call from the attorney','The physician’s verbal approval only','Nothing, because attorneys can see all records'],'D','Records are released only with the patient’s written authorization or a valid legal order such as a court-ordered subpoena.',BLESI),
  q(LEGAL,'The office receives a subpoena for a patient’s records. What should the MA do first?','Notify the physician and follow office policy',['Mail the entire record immediately','Throw the subpoena away','Call the patient’s family'],'A','Subpoenas must be handled according to office policy and legal guidance. The physician or office manager should be informed, and only the requested records are released.',BLESI),
  q(OFF,'An office schedules three patients at the start of each hour and sees them in order of arrival. What is this scheduling method?','Wave scheduling',['Stream scheduling','Double booking','Open hours'],'C','Wave scheduling books several patients at the top of the hour, allowing for late arrivals and varying visit lengths. Stream scheduling gives each patient a set time.',BLESI),
  q(OFF,'A patient misses an appointment without calling. What should the MA do?','Document the no-show in the patient’s record',['Delete the appointment without a note','Call the patient’s employer','Bill the patient’s insurance for the visit'],'B','Documenting no-shows protects the practice legally, especially if the patient’s condition worsens, and helps the provider follow up.',BLESI),
  q(OFF,'What does accounts receivable represent for a medical practice?','Money owed to the practice',['Money the practice owes to suppliers','Cash kept in the petty cash box','Salaries paid to employees'],'D','Accounts receivable is income that has been earned but not yet collected from patients and insurers. Money the practice owes is accounts payable.',BLESI),
  q(OFF,'Why should checks be stamped “For Deposit Only” with the practice’s account number when received?','To protect them if lost or stolen',['To make them cash immediately','To speed insurance payments','To show the patient has a balance'],'A','A restrictive endorsement limits how a check can be used, protecting the practice if the check is lost or stolen before deposit.',BLESI),
  q(OFF,'How does a patient portal help a medical practice?','Patients can securely view results and message staff',['It replaces the need for an EHR','It lets patients change their own records','It is used only for billing insurance'],'C','Patient portals give secure online access to results, appointments, refill requests and messages, improving communication and engagement.',BLESI),
  q(INS,'Which code set is used to report diagnoses?','ICD-10-CM',['CPT','HCPCS Level II','NDC'],'B','ICD-10-CM codes describe diagnoses (why the service was given). CPT codes describe procedures and services (what was done).',BLESI),
  q(INS,'Which codes are used to report ambulance services and durable medical equipment?','HCPCS Level II',['ICD-10-CM','CPT Category I','ICD-10-PCS'],'D','HCPCS Level II codes, which start with a letter, cover supplies, equipment, ambulance services and some drugs not in CPT.',BLESI),
  q(INS,'What is a deductible?','The amount the patient pays before insurance begins paying',['The monthly cost of the insurance plan','A set fee paid at each office visit','The percentage the patient pays after insurance'],'A','The deductible must be met each year before the plan pays benefits. The premium is the plan’s regular cost, and a copay is a fixed fee per visit.',BLESI),
  q(INS,'A plan pays 80% of allowed charges and the patient pays 20%. What is the patient’s 20% called?','Coinsurance',['Copayment','Premium','Deductible'],'C','Coinsurance is the patient’s percentage share after the deductible. A copayment is a fixed dollar amount.',BLESI),
  q(INS,'Which part of Medicare covers outpatient physician services?','Part B',['Part A','Part C','Part D'],'B','Part A covers inpatient hospital care, Part B covers outpatient and physician services, Part C is Medicare Advantage, and Part D covers prescription drugs.',BLESI),
  q(INF,'How does surgical asepsis differ from medical asepsis?','It eliminates all microorganisms from an area',['It reduces the number of microorganisms','It uses only soap and water','It is used for routine office visits'],'D','Medical asepsis (clean technique) reduces the number and spread of microorganisms. Surgical asepsis (sterile technique) removes all microorganisms and spores.',BLESI),
  q(INF,'Which conditions are typical for steam sterilization in an autoclave?','About 250 °F at 15 psi for 20–30 minutes',['About 150 °F at 5 psi for 5 minutes','About 212 °F with no pressure for 2 minutes','About 350 °F of dry heat for 10 minutes'],'A','Steam under pressure at about 250 °F (121 °C) and 15 psi for 20–30 minutes kills microorganisms and spores. Times vary by load.',BLESI),
  q(INF,'What is the first step in preparing used instruments for sterilization?','Sanitizing to remove debris',['Wrapping them in sterile paper','Placing them directly in the autoclave','Soaking them in alcohol'],'C','Instruments must be cleaned of blood and tissue first, because debris shields microorganisms from the sterilizing agent.',BLESI),
  q(INF,'Which rule applies to a sterile field?','Anything below waist level is considered contaminated',['Sterile items may be reached across without concern','A 1-inch border of the field is sterile','Sterile items can be reused if they look clean'],'B','Only items above waist level and in view are considered sterile. The 1-inch border of a sterile field is considered contaminated.',BLESI),
  q(INF,'After cleaning up a blood spill on an exam table, which product should be applied?','A registered disinfectant',['Plain warm tap water','Hand lotion','Household glass cleaner'],'D','OSHA requires contaminated surfaces to be decontaminated with an appropriate disinfectant. Gloves are worn throughout.',BLESI),
  q(SPEC,'Why is a midstream clean-catch technique used for urine cultures?','To reduce contamination from the skin and urethra',['To collect the most concentrated urine','To measure total urine output','To check for glucose only'],'A','Cleansing the area and collecting the middle of the stream flushes away bacteria at the opening of the urethra, so the culture reflects the bladder urine.',BLESI),
  q(SPEC,'When collecting a throat culture, where should the swab touch?','The tonsils and back of the throat',['The tongue and cheeks','The roof of the mouth only','The teeth and gums'],'C','The swab is rubbed over the tonsils and posterior pharynx, avoiding the tongue and cheeks to prevent contamination with mouth flora.',BLESI),
  q(SPEC,'Why might a patient be told to avoid red meat before a guaiac fecal occult blood test?','Red meat can cause a false-positive result',['Red meat hides colon cancer','Red meat makes the stool too hard','Red meat changes the stool color permanently'],'B','Hemoglobin in red meat and some foods can react with the guaiac test, causing false positives. Immunochemical tests (FIT) are not affected by diet.',BLESI),
  q(SPEC,'A urine specimen cannot be tested within 1 hour. What should be done?','Refrigerate it',['Leave it on the counter','Add hot water','Freeze and thaw it twice'],'D','At room temperature, bacteria multiply and cells and casts break down, altering results. Refrigeration preserves the sample for a short time.',BLESI),
  q(SPEC,'Why is a chain-of-custody form used for a workplace drug screen?','To document everyone who handles the specimen',['To bill the employer correctly','To record the patient’s medications','To track how long the test takes'],'A','Chain of custody proves the specimen was not tampered with, so results can be used for legal or employment decisions.',BLESI),
  q(DX,'Where is ECG lead V1 placed?','Fourth intercostal space, right of the sternum',['Fourth intercostal space, left of the sternum','Fifth intercostal space, left midclavicular line','Fifth intercostal space, left midaxillary line'],'C','V1 is at the fourth intercostal space at the right sternal border, V2 at the left sternal border, and V4 at the fifth intercostal space at the midclavicular line.',BLESI),
  q(DX,'An ECG tracing shows erratic, jagged interference because the patient is shivering. What is this artifact?','Somatic tremor',['Wandering baseline','AC interference','Interrupted baseline'],'B','Muscle movement causes somatic tremor. Wandering baseline comes from poor electrode contact or breathing, and AC interference from electrical equipment.',BLESI),
  q(DX,'A patient’s visual acuity is 20/40. What does this mean?','The patient sees at 20 feet what normal vision sees at 40 feet',['The patient sees at 40 feet what normal vision sees at 20 feet','The patient has 40% vision loss','The patient needs no correction'],'D','The top number is the testing distance; the bottom is the distance at which a person with normal vision can read the same line.',BLESI),
  q(DX,'Which spirometry measurement is the volume of air forcefully exhaled in the first second?','FEV1',['FVC','Tidal volume','Peak flow'],'A','FEV1 is forced expiratory volume in 1 second. The FEV1/FVC ratio helps identify obstructive diseases such as asthma and COPD.',BLESI),
  q(DX,'A hemoglobin A1c test reflects average blood glucose over about how long?','2 to 3 months',['The last 24 hours','1 week','About 1 year'],'C','Glucose attaches to hemoglobin for the life of the red blood cell (about 120 days), so A1c reflects average control over roughly 2–3 months.',BLESI),
  q(CLIN,'What is the usual maximum volume for an intramuscular injection in an adult’s deltoid?','1 mL',['3 mL','5 mL','10 mL'],'B','The deltoid is a small muscle, so volumes are generally limited to about 0.5–1 mL. Larger volumes go into the ventrogluteal or vastus lateralis.',BLESI),
  q(CLIN,'How does needle gauge relate to needle size?','Higher gauge means a thinner needle',['Higher gauge means a thicker needle','Gauge measures needle length','Gauge does not affect the diameter'],'A','Gauge is inversely related to diameter: a 25-gauge needle is thinner than an 18-gauge needle. Length is measured separately in inches.',BLESI),
  q(CLIN,'Sutures on the face are usually removed sooner than sutures elsewhere. About when?','After 3 to 5 days',['After 10 to 14 days','After 3 weeks','After 6 weeks'],'D','The face has a rich blood supply and heals quickly; removing sutures early limits scarring. Areas under more tension, such as joints, keep sutures longer.',BLESI),
  q(CLIN,'When irrigating an adult’s ear, how should the pinna be pulled?','Up and back',['Down and back','Straight down','Forward'],'C','In adults, pulling the pinna up and back straightens the ear canal. In young children, it is pulled down and back.',BLESI),
  q(CLIN,'After giving an injection, why should the patient remain in the office for 15–30 minutes?','To watch for an allergic reaction',['To let the medication dry','To recheck the injection site for bleeding only','To complete the billing paperwork'],'B','Severe reactions such as anaphylaxis usually begin soon after an injection. Observing the patient allows quick treatment if needed.',BLESI),
  q(EXAM,'In which position is the patient placed for a pelvic examination?','Lithotomy',['Sims’','Prone','Trendelenburg'],'D','In lithotomy, the patient lies on the back with feet in stirrups. Sims’ (left side-lying) is used for rectal exams.',BLESI),
  q(EXAM,'Which position is commonly used for a rectal exam or enema?','Sims’ position',['Fowler’s position','Supine position','Knee-chest position only'],'A','In Sims’ position, the patient lies on the left side with the right knee bent toward the chest, giving access to the rectum.',BLESI),
  q(EXAM,'The physician taps on the patient’s abdomen and listens to the sounds produced. Which exam technique is this?','Percussion',['Palpation','Auscultation','Inspection'],'C','Percussion is tapping to assess the size and density of organs. Palpation is feeling, auscultation is listening with a stethoscope, and inspection is looking.',BLESI),
  q(EXAM,'Until what age is head circumference usually measured at well-child visits?','2 to 3 years',['6 months old','10 years','18 years'],'B','The head grows rapidly in the first years. Measuring head circumference until about age 2–3 helps detect abnormal brain growth.',BLESI),
  q(EXAM,'Which BMI range is considered healthy weight for adults?','18.5 to 24.9',['25.0 to 29.9','30.0 to 34.9','Below 18.5'],'D','A BMI of 25–29.9 is overweight, 30 or above is obese, and below 18.5 is underweight.',BLESI)
 ],67)
};
